import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Courses = () => {
  const navigate = useNavigate();
  
  // Updated course data to match the rich UI structure in the image
  const [courses, setCourses] = useState([
    { 
      id: 1, 
      title: 'Java Development', 
      price: 5000,
      badge: 'Bestseller',
      rating: '4.9',
      learners: '2,850+',
      description: 'Master Java programming, OOP concepts and enterprise development with practical projects.',
      topics: ['Core Java', 'OOP', 'Collections', 'Spring Boot', 'SQL'],
      headerGradient: 'from-[#0f172a] via-[#1e1b4b] to-[#0b0f19]'
    },
    { 
      id: 2, 
      title: 'Python Development', 
      price: 6500,
      badge: 'Popular',
      rating: '4.9',
      learners: '3,200+',
      description: 'Build strong Python fundamentals and develop real-world applications with confidence.',
      topics: ['Python', 'OOP', 'Data Structures', 'Django', 'Projects'],
      headerGradient: 'from-[#1e3a8a] via-[#3b82f6]/20 to-[#0b0f19]'
    },
    { 
      id: 3, 
      title: 'Java Full Stack', 
      price: 8000,
      badge: 'Career Track',
      rating: '4.8',
      learners: '2,100+',
      description: 'Become a complete full-stack developer with Java, Spring Boot, React and databases.',
      topics: ['Java', 'Spring Boot', 'HTML/CSS', 'React', 'MySQL'],
      headerGradient: 'from-[#7f1d1d]/40 via-[#991b1b]/20 to-[#0b0f19]'
    },
    { 
      id: 4, 
      title: 'Python Full Stack', 
      price: 7500,
      badge: 'Trending',
      rating: '4.9',
      learners: '2,400+',
      description: 'Learn modern full-stack development using Python, Django, React and databases.',
      topics: ['Python', 'Django', 'React', 'JavaScript', 'PostgreSQL'],
      headerGradient: 'from-[#0369a1]/40 via-[#0284c7]/20 to-[#0b0f19]'
    },
    // Mocking a few more to populate the grid
    { 
      id: 5, 
      title: 'React Native Mobile Dev', 
      price: 4000,
      badge: 'New',
      rating: '4.7',
      learners: '1,500+',
      description: 'Build cross-platform mobile applications for iOS and Android using React Native.',
      topics: ['React Native', 'Expo', 'Redux', 'API Integration', 'UI/UX'],
      headerGradient: 'from-[#4c1d95]/40 via-[#6d28d9]/20 to-[#0b0f19]'
    },
    { 
      id: 6, 
      title: 'Cloud Computing with AWS', 
      price: 5500,
      badge: 'High Demand',
      rating: '4.8',
      learners: '1,800+',
      description: 'Master cloud infrastructure, deployment, and AWS core services.',
      topics: ['EC2 & S3', 'IAM Security', 'Lambda', 'VPC', 'Deployment'],
      headerGradient: 'from-[#ea580c]/30 via-[#f97316]/10 to-[#0b0f19]'
    }
  ]);

  const handleEnroll = (course) => {
    // Navigating to student details as per your previous flow
    navigate('/student-details', { state: { course } });
  };

  return (
    <div className="p-8 max-w-[1400px] mx-auto min-h-screen bg-[#07090e] text-gray-200 font-sans">
      <h1 className="text-3xl md:text-4xl font-bold mb-10 text-center text-gray-100 tracking-wide">
        Explore Our Programs
      </h1>
      
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {courses.map((course) => (
          <div 
            key={course.id} 
            className="bg-[#0b0f19] border border-[#1e293b] rounded-xl overflow-hidden flex flex-col transition-all duration-300 hover:border-blue-500/40 hover:shadow-[0_0_15px_rgba(37,99,235,0.1)] group"
          >
            {/* Top Banner / Image Area */}
            <div className={`h-32 bg-gradient-to-b ${course.headerGradient} relative p-4 flex items-start`}>
              <span className="bg-[#007bff] text-white text-[10px] uppercase tracking-wider px-3 py-1 rounded-full font-bold shadow-md">
                {course.badge}
              </span>
            </div>

            {/* Card Content Area */}
            <div className="p-5 flex-1 flex flex-col">
              {/* Academy Name */}
              <p className="text-[10px] text-gray-400 mb-2 tracking-widest uppercase">
                VIGHNAVI ACADEMY
              </p>
              
              {/* Rating */}
              <div className="text-yellow-500 text-xs font-bold mb-3 flex items-center gap-1">
                ⭐ {course.rating} <span className="text-gray-400 font-normal ml-1">({course.learners} learners)</span>
              </div>
              
              {/* Title & Description */}
              <h2 className="text-xl font-semibold text-gray-100 mb-2 group-hover:text-blue-400 transition-colors">
                {course.title}
              </h2>
              <p className="text-gray-400 text-sm mb-4 line-clamp-2 min-h-[40px]">
                {course.description}
              </p>

              {/* Topics Checklist box */}
              <div className="border border-[#1e293b] bg-[#07090e]/50 rounded-lg p-4 mb-5">
                <ul className="text-gray-300 text-xs space-y-2">
                  {course.topics.map((topic, index) => (
                    <li key={index} className="flex items-center gap-2">
                      <span className="text-gray-500">✓</span> {topic}
                    </li>
                  ))}
                </ul>
              </div>

              {/* Footer info (Career-focused & Price) */}
              <div className="mt-auto flex justify-between items-end mb-4">
                <div className="flex items-center gap-2 text-xs text-gray-400">
                  <span>🎓</span> Career-focused
                </div>
                <div className="text-right">
                  <span className="block text-[10px] text-gray-500 mb-1">Course Fee</span>
                  <span className="text-blue-400 font-bold text-lg">₹{course.price}</span>
                </div>
              </div>

              {/* Action Button using user requested color #090949 */}
              <button 
                onClick={() => handleEnroll(course)}
                className="w-full bg-[#090949] text-white py-3 rounded-lg hover:bg-[#0a0a5c] hover:shadow-[0_0_10px_rgba(9,9,73,0.5)] transition-all duration-200 font-semibold text-sm tracking-wide border border-[#1e293b]"
              >
                Enroll Now →
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Courses;
